import json, os, sys, urllib.request, urllib.error
URL = os.environ["PACKIGNORE_URL"]
def query(files):
    req = urllib.request.Request(URL + "/ignored", data=json.dumps({"files": files}).encode(),
                                 headers={"Content-Type": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=60) as r:
            return json.load(r)["ignored"]
    except urllib.error.HTTPError as e:
        body = e.read()
        try: return ("ERROR", e.code, json.loads(body))
        except Exception: return ("ERROR", e.code, body)
def t(pi, paths, **extra):
    files = {".packignore": pi}
    files.update({p: None for p in paths})
    files.update(extra)
    return query(files)
if __name__ == "__main__":
    print(query(json.loads(sys.argv[1])))
