from q import *
import sys
F = "abcdefghijklmnopqrstuvwxyz"
def cal(s): return F[:s] + "?"*(len(F)-s)
def rel(X, Y, path):
    """compare X (as neg) vs Y (pos). returns 'X' if X wins both orders, 'Y', or 'tie'"""
    r1 = path in t("!"+X+"\n"+Y, [path])   # X first, Y last -> excluded if Y wins
    r2 = path in t(Y+"\n!"+X, [path])
    if not r1 and not r2: return "X"
    if r1 and r2: return "Y"
    if r1 and not r2: return "tie"
    return "weird"
def score(X, path=F, prefix=""):
    # binary search s such that rel(X, cal(s)) == tie
    lo, hi = 0, len(F)
    res = {}
    while lo <= hi:
        m = (lo+hi)//2
        r = rel(X, prefix+cal(m), path)
        if r == "tie": return m
        if r == "X": lo = m+1
        elif r == "Y": hi = m-1
        else: return ("weird", m)
    return ("between", hi, lo)
if __name__ == "__main__":
    for x in sys.argv[1:]:
        print(repr(x), score(x))
