import unicodedata as u, sys, itertools
from q import query
N=u.normalize
Ks = {
 "cf_nfc": lambda s: N("NFC",s).casefold(),
 "cf_nfd": lambda s: N("NFD",s).casefold(),
 "nfc_cf": lambda s: N("NFC",s.casefold()),
 "nfd_cf": lambda s: N("NFD",s.casefold()),
 "nfc_cf_nfc": lambda s: N("NFC",N("NFC",s).casefold()),
 "nfd_cf_nfd": lambda s: N("NFD",N("NFD",s).casefold()),
 "nfc_cf_nfd": lambda s: N("NFC",N("NFD",s).casefold()),
 "nfd_cf_nfc": lambda s: N("NFD",N("NFC",s).casefold()),
}
# candidate strings
chars=[chr(c) for c in range(0x80,0x2200) if u.category(chr(c))[0] in "LM"]
cands=set()
for c in chars:
    for f in [lambda x:x, lambda x:N("NFD",x), lambda x:N("NFC",x), lambda x:x.casefold(), lambda x:x.upper(), lambda x:x.lower(), lambda x:N("NFD",x.casefold()), lambda x:N("NFC",x.casefold())]:
        cands.add(f(c))
groups={}
cands=sorted(cands)
# find pairs where key functions disagree
from collections import defaultdict
pairs=[]
idx=defaultdict(list)
for s in cands:
    for k,f in Ks.items():
        idx[(k,f(s))].append(s)
seen=set()
for (k,key),lst in idx.items():
    for a,b in itertools.combinations(lst,2):
        if (a,b) in seen: continue
        seen.add((a,b))
        sig=tuple(Ks[kk](a)==Ks[kk](b) for kk in Ks)
        if not all(sig): pairs.append((sig,a,b))
bysig={}
for sig,a,b in pairs: bysig.setdefault(sig,[]).append((a,b))
for sig,lst in bysig.items():
    for a,b in lst[:3]:
        d={".packignore":"*", "x"+a:None, "x"+b:None}
        r=query(d)
        merged = len([p for p in r if p!=".packignore"])==1
        print(sig, ascii(a), ascii(b), "merged" if merged else "separate", ascii(r) if isinstance(r,tuple) else "")
print(list(Ks))
EOF
