    regex = re.compile("|".join(f"(?:{a})" for a in alternatives), re.DOTALL)
    return negated, dir_only, score, regex


def _parse(content):
    rules = []
    for line in content.splitlines():
        line = line.strip()
        if not line or line.startswith(";"):
            continue
        rules.append(_compile(line))
    return rules


# --- evaluation -----------------------------------------------------------

